"use strict";(globalThis.webpackChunksimple_jwt_login_website=globalThis.webpackChunksimple_jwt_login_website||[]).push([[8130],{77735(e){e.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"/new-website-design-2026/","metadata":{"permalink":"/blog/new-website-design-2026/","editUrl":"https://github.com/simple-jwt-login/website/tree/main/blog/2026-03-11-new-website-design.md","source":"@site/blog/2026-03-11-new-website-design.md","title":"A Faster, Smarter New Website Design","description":"The Simple JWT Login website has a new design, with a cleaner UI, built-in search, AI-friendly content, and improved SEO.","date":"2026-03-11T00:00:00.000Z","tags":[{"inline":false,"label":"News","permalink":"/blog/tags/tags/news","description":"Plugin news"},{"inline":false,"label":"WordPress Plugin","permalink":"/blog/tags/tags/wordpress-plugin","description":"WordPress plugin tips, features, and usage guides"}],"readingTime":1.74,"hasTruncateMarker":true,"authors":[{"name":"Nicu Micle","title":"Creator of Simple JWT Login","url":"https://github.com/nicumicle","page":{"permalink":"/blog/authors/nicumicle"},"socials":{"x":"https://x.com/nicumicle","github":"https://github.com/nicumicle"},"imageURL":"https://github.com/nicumicle.png","key":"nicumicle"}],"frontMatter":{"title":"A Faster, Smarter New Website Design","description":"The Simple JWT Login website has a new design, with a cleaner UI, built-in search, AI-friendly content, and improved SEO.","slug":"/new-website-design-2026/","hide_table_of_contents":false,"authors":"nicumicle","tags":["news","wordpress-plugin"],"keywords":["Simple JWT Login website","new design","Docusaurus","documentation","search","LLMs.txt"],"image":"/assets/images/social-card.png"},"unlisted":false,"nextItem":{"title":"Headless WordPress: JWT Auth Done Right","permalink":"/blog/headless-wordpress-jwt-authentication/"}},"content":"The Simple JWT Login website just got a major update. The plugin hasn\'t changed - but everything around it has. From the homepage to the blog to the docs navigation, here\'s a look at what\'s new and why it changed.\\n\\n\x3c!-- truncate --\x3e\\n\\n## Refreshed UI\\n\\nThe entire visual design has been overhauled. Every page - homepage, contact, donate, blog - now uses a consistent design language with refined typography, better spacing, and clear calls to action.\\n\\nThe homepage in particular got a lot of attention. Feature cards now have sharper copy that explains *what the feature does* rather than just naming it. The stats section (active installs, downloads, ratings) gives newcomers quick confidence, and the CTA buttons are more prominent.\\n\\nThe blog also has a custom layout: post cards show the author, date, tags, and a description at a glance - no more bare-bones list.\\n\\n## Built-in Search\\n\\nThe site now has **full-text local search** powered by [`@easyops-cn/docusaurus-search-local`](https://github.com/easyops-cn/docusaurus-search-local). It indexes docs and blog posts, works entirely client-side (no external service), and is available from any page.\\n\\nIf you\'ve ever tried to find a specific configuration option or remember which doc covers token revocation - just search for it now.\\n\\n## LLMs.txt Support\\n\\nThe site now generates an `llms.txt` file (and `llms-full.txt`) via the [`@signalwire/docusaurus-plugin-llms-txt`](https://github.com/signalwire/docusaurus-plugin-llms-txt) plugin. This is a [community standard](https://llmstxt.org/) for making documentation AI-friendly.\\n\\nIf you\'re using an AI assistant to help integrate Simple JWT Login into your app, it can now read structured, clean content from this site rather than parsing raw HTML.\\n\\n## Release Notes\\n\\nThe [Releases](/releases) section is now live with structured changelogs for recent plugin versions (3.6.2, 3.6.3, 3.6.4, 3.6.5). Going forward, every plugin release gets a matching entry there.\\n\\n---\\n\\nThe plugin itself hasn\'t changed - but if you haven\'t visited the docs in a while, it\'s worth a look. And if you run into anything that feels off or missing, [open an issue on GitHub](https://github.com/nicumicle/simple-jwt-login/issues)."},{"id":"/headless-wordpress-jwt-authentication/","metadata":{"permalink":"/blog/headless-wordpress-jwt-authentication/","editUrl":"https://github.com/simple-jwt-login/website/tree/main/blog/2026-03-10-headless-wordpress-jwt-authentication.md","source":"@site/blog/2026-03-10-headless-wordpress-jwt-authentication.md","title":"Headless WordPress: JWT Auth Done Right","description":"Add production-ready JWT authentication to your headless WordPress setup - from token generation to protected endpoints.","date":"2026-03-10T00:00:00.000Z","tags":[{"inline":false,"label":"Tutorial","permalink":"/blog/tags/tags/tutorial","description":"Tutorials and guides for Simple JWT Login"},{"inline":false,"label":"Headless WordPress","permalink":"/blog/tags/tags/headless-wordpress","description":"Articles about headless WordPress architecture and JWT authentication"},{"inline":false,"label":"JWT Authentication","permalink":"/blog/tags/tags/jwt-authentication","description":"Articles about JSON Web Token (JWT) authentication"},{"inline":false,"label":"Security","permalink":"/blog/tags/tags/security","description":"WordPress REST API security and authentication best practices"}],"readingTime":8.07,"hasTruncateMarker":true,"authors":[{"name":"Nicu Micle","title":"Creator of Simple JWT Login","url":"https://github.com/nicumicle","page":{"permalink":"/blog/authors/nicumicle"},"socials":{"x":"https://x.com/nicumicle","github":"https://github.com/nicumicle"},"imageURL":"https://github.com/nicumicle.png","key":"nicumicle"}],"frontMatter":{"title":"Headless WordPress: JWT Auth Done Right","description":"Add production-ready JWT authentication to your headless WordPress setup - from token generation to protected endpoints.","slug":"/headless-wordpress-jwt-authentication/","hide_table_of_contents":false,"authors":"nicumicle","tags":["tutorials","headless-wordpress","jwt-authentication","security"],"keywords":["headless WordPress","JWT authentication","WordPress REST API","Simple JWT Login","token-based auth","headless CMS","Next.js WordPress","React WordPress"],"image":"/assets/images/social-card.png"},"unlisted":false,"prevItem":{"title":"A Faster, Smarter New Website Design","permalink":"/blog/new-website-design-2026/"},"nextItem":{"title":"JWT Security Hardening Guide","permalink":"/blog/simple-jwt-login-security-hardening/"}},"content":"[Headless WordPress](/headless-wordpress) has gone mainstream. Teams reach for it when they want WordPress\'s content management experience paired with a modern front-end - React, Next.js, Vue, or a mobile app. The REST API makes that possible, but it leaves one critical piece unresolved: **authentication**.\\n\\nWordPress\'s built-in auth is cookie-based and browser-centric. It doesn\'t translate cleanly to API-first architectures. That\'s the gap Simple JWT Login fills, and in this article I\'ll walk through a complete, realistic setup.\\n\\n\x3c!--truncate--\x3e\\n\\n## What You\'ll Build\\n\\nA headless WordPress backend with:\\n\\n- JWT-based login (email + password \u2192 token)\\n- Token refresh before expiry\\n- Protected REST endpoints that require a valid JWT\\n- User registration via API\\n- Password reset flow\\n- Auto-login links for email campaigns\\n\\nAll of this is handled by [Simple JWT Login](https://wordpress.org/plugins/simple-jwt-login/) with zero custom PHP beyond optional hooks.\\n\\n---\\n\\n## Installation and Initial Configuration\\n\\nInstall Simple JWT Login from the WordPress plugin repository, then navigate to **Simple JWT Login** in your WordPress admin sidebar.\\n\\nThe first setting to configure is the signing key, in the **ELSE** row of **JWT Verification Rules**. This secret signs and verifies tokens. Treat it like a database password: long, random, and kept out of the database where possible - the plugin can read it from `wp-config.php`.\\n\\n```\\nSettings > Simple JWT Login > General > JWT Verification Rules\\n```\\n\\nIn the same row, select your **algorithm**. For most setups `HS256` (HMAC SHA-256) is the right default. If you need asymmetric signing - for example, to let a third-party service verify tokens without knowing the secret - switch to `RS256` and configure your public/private key pair.\\n\\nThen turn on **Allow JWT Authentication** under **Authentication** - every endpoint is disabled by default. While you\'re there, set a reasonable **JWT Expiration**. Sixty minutes is a sensible starting point for most web apps; mobile apps often use longer windows paired with token refresh.\\n\\n---\\n\\n## Generating a Token\\n\\nOnce the plugin is active, your WordPress site immediately has an authentication endpoint:\\n\\n```bash\\ncurl -X POST \\"https://example.com/wp-json/simple-jwt-login/v1/auth\\" \\\\\\n  -H \\"Content-Type: application/json\\" \\\\\\n  -d \'{\\n    \\"email\\": \\"user@example.com\\",\\n    \\"password\\": \\"their_password\\"\\n  }\'\\n```\\n\\nA successful response looks like this:\\n\\n```json\\n{\\n  \\"success\\": true,\\n  \\"data\\": {\\n    \\"jwt\\": \\"eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9...\\",\\n    \\"refresh_token\\": \\"a1b2c3d4e5f6...\\"\\n  }\\n}\\n```\\n\\nThe `refresh_token` is only there when refresh tokens are turned on. Store the JWT client-side (memory or an `HttpOnly` cookie - avoid `localStorage` for sensitive apps) and attach it to subsequent requests.\\n\\nInstead of `email`, you can send `username`, or `login`, which accepts either one.\\n\\n---\\n\\n## Making Authenticated Requests\\n\\nOnce you have a token, include it in the `Authorization` header on every protected request. To use it on WordPress\'s own routes such as `/wp/v2/users/me`, turn on **JWT Middleware for all WordPress endpoints** under **General \u2192 Integration Options**:\\n\\n```bash\\ncurl \\"https://example.com/wp-json/wp/v2/users/me\\" \\\\\\n  -H \\"Authorization: Bearer eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9...\\"\\n```\\n\\nThe plugin can also read the token from a query parameter (`?JWT=<token>`), a cookie, or the session - see [JWT Input Sources](/docs/configuration#jwt-input-sources). Prefer the header: URLs end up in server logs.\\n\\n---\\n\\n## Refreshing Tokens\\n\\nShort-lived tokens are more secure, but they require your client to handle expiry gracefully. Turn on refresh tokens, and `/auth` returns a `refresh_token` next to the JWT. Exchange it at the refresh endpoint:\\n\\n```bash\\ncurl -X POST \\"https://example.com/wp-json/simple-jwt-login/v1/auth/refresh\\" \\\\\\n  -H \\"Content-Type: application/json\\" \\\\\\n  -d \'{\\"refresh_token\\": \\"a1b2c3d4e5f6...\\"}\'\\n```\\n\\nThe response contains a new JWT and a new refresh token. See [Refresh token](/docs/refresh-token/) for the details. A typical front-end pattern: check the token\'s `exp` claim before each request, and if it\'s within a few minutes of expiry, refresh proactively rather than reacting to a 401.\\n\\n---\\n\\n## Protecting Your REST Endpoints\\n\\nA headless WordPress site often exposes more REST routes than intended. Simple JWT Login\'s **Endpoint Protection** feature lets you require a valid JWT for any route.\\n\\nThe most secure posture for a private API: enable **\\"Protect all endpoints\\"** and then whitelist only the routes that must be public.\\n\\n```\\nSettings > Simple JWT Login > Protect Endpoints\\nMode: Protect all WordPress Endpoints\\n```\\n\\nFor a typical blog-style API you might whitelist:\\n\\n- `GET /wp-json/wp/v2/posts` - public post listing\\n- `GET /wp-json/wp/v2/categories` - taxonomy data\\n- `POST /wp-json/simple-jwt-login/v1/auth` - login itself\\n\\nEvery other route - user data, media uploads, post creation - requires a valid JWT.\\n\\nYou can also protect routes **by HTTP method**. If your front-end needs `GET` on posts to be public but `POST` (creating posts) to be authenticated, add a rule for each method. Browser apps should prefer specific methods over **ALL**, because an **ALL** rule also blocks the CORS preflight - see [Troubleshooting](/docs/troubleshooting/).\\n\\n---\\n\\n## User Registration via API\\n\\nIf your application handles its own onboarding flow, you can create WordPress users directly through the API. First, enable registration under:\\n\\n```\\nSettings > Simple JWT Login > Register User\\n```\\n\\nFor security, always pair registration with an **Auth Code** - an API key that must accompany registration requests. This prevents anyone with your API URL from creating arbitrary accounts.\\n\\n```bash\\ncurl -X POST \\"https://example.com/wp-json/simple-jwt-login/v1/users\\" \\\\\\n  -H \\"Content-Type: application/json\\" \\\\\\n  -d \'{\\n    \\"email\\": \\"newuser@example.com\\",\\n    \\"password\\": \\"initial_password\\",\\n    \\"first_name\\": \\"Jane\\",\\n    \\"last_name\\": \\"Doe\\",\\n    \\"AUTH_KEY\\": \\"YOUR_REGISTRATION_AUTH_CODE\\"\\n  }\'\\n```\\n\\nYou can also turn on **Generate a random password**, so the request doesn\'t need a `password` at all.\\n\\nIP address restrictions and email domain allowlists add further layers of control over who can register.\\n\\n---\\n\\n## Password Reset Flow\\n\\nThe plugin ships a full password reset flow accessible via API, which is often missing from DIY JWT implementations.\\n\\n**Step 1 - Request a reset code:**\\n\\n```bash\\ncurl -X POST \\"https://example.com/wp-json/simple-jwt-login/v1/user/reset_password\\" \\\\\\n  -H \\"Content-Type: application/json\\" \\\\\\n  -d \'{\\"email\\": \\"user@example.com\\"}\'\\n```\\n\\n**Step 2 - Submit the new password with the code:**\\n\\n```bash\\ncurl -X PUT \\"https://example.com/wp-json/simple-jwt-login/v1/user/reset_password\\" \\\\\\n  -H \\"Content-Type: application/json\\" \\\\\\n  -d \'{\\n    \\"email\\": \\"user@example.com\\",\\n    \\"code\\": \\"RESET_CODE_FROM_EMAIL\\",\\n    \\"new_password\\": \\"new_secure_password\\"\\n  }\'\\n```\\n\\nThree reset flows are available:\\n\\n- **Save code in database only**: No email is sent, so your front end can deliver the code its own way.\\n- **Send default WordPress reset email**: Uses WordPress\'s built-in email template.\\n- **Send custom email**: You define the subject and body using variables like `{{CODE}}`, `{{NAME}}`, and `{{EMAIL}}`.\\n\\nThe custom template mode is ideal for headless apps that have their own transactional email design system and don\'t want WordPress\'s default styling.\\n\\n---\\n\\n## Auto-Login Links for Email Campaigns\\n\\nOne of the most underrated features: generate a URL that logs a user in automatically when clicked.\\n\\nEnable auto-login under:\\n\\n```\\nSettings > Simple JWT Login > Autologin\\n```\\n\\nThen generate a JWT for the target user and construct the URL:\\n\\n```\\nhttps://example.com/?rest_route=/simple-jwt-login/v1/autologin&JWT=<user_jwt>&redirectUrl={{site_url}}/account/dashboard\\n```\\n\\nWhen the user clicks that link, Simple JWT Login authenticates them silently and redirects them to their dashboard - already logged in.\\n\\nThe `redirectUrl` parameter works when **Honor the `redirectUrl` parameter** is on, and supports dynamic variables (`{{user_id}}`, `{{user_email}}`, `{{user_first_name}}`, and more), so each link can route the user to a personalized destination. Pair this with the **MailPoet add-on** and you have one-click autologin directly inside email campaigns without a single line of custom code.\\n\\n---\\n\\n## Enriching the JWT with Custom Data\\n\\nThe JWT payload carries the claims you select under **Authentication \u2192 JWT payload parameters**, such as `id`, `email`, and `exp`. For most front-ends you\'ll want to include additional user data to avoid extra API calls after login.\\n\\nUse the `simple_jwt_login_jwt_payload_auth` filter, which runs on `/auth` (turn it on under **Hooks** first):\\n\\n```php\\nadd_filter(\'simple_jwt_login_jwt_payload_auth\', function($payload, $request) {\\n    $user = get_user_by(\'id\', $payload[\'id\']);\\n    if (!$user) {\\n        return $payload;\\n    }\\n    $payload[\'display_name\'] = $user->display_name;\\n    $payload[\'roles\']        = $user->roles;\\n    $payload[\'avatar\']       = get_avatar_url($user->ID);\\n    return $payload;\\n}, 10, 2);\\n```\\n\\nThis example assumes `id` is one of the selected payload claims. Your front-end can now decode the JWT and immediately render the user\'s name and avatar without an additional `/users/me` request.\\n\\n---\\n\\n## Revoking Tokens\\n\\nWhen a user logs out or changes their password, you\'ll want to invalidate their existing tokens. Simple JWT Login provides a revoke endpoint:\\n\\n```bash\\ncurl -X POST \\"https://example.com/wp-json/simple-jwt-login/v1/auth/revoke\\" \\\\\\n  -H \\"Authorization: Bearer <token>\\"\\n```\\n\\nRevoked tokens are blocked server-side and rejected on later requests, even if they haven\'t technically expired yet.\\n\\n---\\n\\n## A Note on CORS\\n\\nIf your front-end is served from a different domain than WordPress - which is almost always the case in headless setups - you\'ll need CORS headers. Configure them in the plugin:\\n\\n```\\nSettings > Simple JWT Login > CORS\\n```\\n\\nList your front-end origin, such as `https://app.example.com`, in **Allow origin**, and include `Authorization` in **Allow headers**. Use the plugin setting rather than only your web server config: since version 4.1.1, the plugin also uses the **Allow origin** list to decide which cross-site requests may authenticate with a JWT. See [CORS](/docs/cors/) for the details.\\n\\n---\\n\\n## Conclusion\\n\\nSimple JWT Login takes what would otherwise be hundreds of lines of custom authentication code and turns it into a configuration exercise. Token generation, refresh, revocation, endpoint protection, user registration, password resets, and auto-login are all covered out of the box.\\n\\nFor teams building headless WordPress - whether the front-end is React, Next.js, Angular, or a Flutter app - it\'s one of the highest-leverage plugins available. Each of those has a [complete, downloadable example](/docs/code-examples/), and the [headless WordPress guide](/headless-wordpress) collects them in one place. The [documentation](/docs/) is thorough, the plugin is actively maintained, and the hooks system means you\'re never painted into a corner when requirements get complex.\\n\\nInstall it, spend an hour on the settings, and your WordPress REST API gets authentication that actually fits modern development patterns."},{"id":"/simple-jwt-login-security-hardening/","metadata":{"permalink":"/blog/simple-jwt-login-security-hardening/","editUrl":"https://github.com/simple-jwt-login/website/tree/main/blog/2026-03-10-security-hardening-guide.md","source":"@site/blog/2026-03-10-security-hardening-guide.md","title":"JWT Security Hardening Guide","description":"A practical checklist for hardening Simple JWT Login in production - algorithm selection, Auth Codes, IP restrictions, and more.","date":"2026-03-10T00:00:00.000Z","tags":[{"inline":false,"label":"Tutorial","permalink":"/blog/tags/tags/tutorial","description":"Tutorials and guides for Simple JWT Login"},{"inline":false,"label":"Security","permalink":"/blog/tags/tags/security","description":"WordPress REST API security and authentication best practices"}],"readingTime":11.85,"hasTruncateMarker":true,"authors":[{"name":"Nicu Micle","title":"Creator of Simple JWT Login","url":"https://github.com/nicumicle","page":{"permalink":"/blog/authors/nicumicle"},"socials":{"x":"https://x.com/nicumicle","github":"https://github.com/nicumicle"},"imageURL":"https://github.com/nicumicle.png","key":"nicumicle"}],"frontMatter":{"title":"JWT Security Hardening Guide","description":"A practical checklist for hardening Simple JWT Login in production - algorithm selection, Auth Codes, IP restrictions, and more.","slug":"/simple-jwt-login-security-hardening/","hide_table_of_contents":false,"authors":"nicumicle","tags":["tutorials","security"],"image":"/assets/images/social-card.png","keywords":["Simple JWT Login","security hardening","WordPress REST API","JWT authentication","Auth Codes"]},"unlisted":false,"prevItem":{"title":"Headless WordPress: JWT Auth Done Right","permalink":"/blog/headless-wordpress-jwt-authentication/"},"nextItem":{"title":"5 Standout Features of Simple JWT Login","permalink":"/blog/top-features-simple-jwt-login/"}},"content":"Installing Simple JWT Login takes minutes. Configuring it securely for production takes a bit more thought. The plugin ships with most sensitive features **disabled by default**, which is the right approach - but it also means the defaults aren\'t always sufficient for a hardened deployment.\\n\\nThis guide works through the main security settings in Simple JWT Login, explains the trade-offs, and gives you a concrete checklist to work from before you go live.\\n\\n\x3c!--truncate--\x3e\\n\\n:::note\\nThis guide covers Simple JWT Login v4. Settings that need a specific release are marked with its version.\\n:::\\n\\n## Threats and Defenses at a Glance\\n\\nStart from what an attacker might do, then check that the matching defense is on:\\n\\n| Attack | Defense | Default |\\n|---|---|---|\\n| Guess the key and forge an admin token | Long random key, outside the database ([section 2](#2-use-a-strong-decryption-key)) | You set the key |\\n| Replay a stolen JWT | Short expiration and revocation ([3](#3-set-a-short-token-expiration), [8](#8-use-token-revocation-for-logout-and-password-changes)) | 60 minutes; revoke endpoint off |\\n| Reuse a JWT issued for another site or app | Expected audience, `aud` (4.2.0) ([11](#11-bind-tokens-to-your-site)) | Off |\\n| Make a visitor\'s browser send their cookie JWT (CSRF) | Cross-site request checks (4.1.1) ([9](#9-configure-cors-carefully)) | Always on |\\n| Log in with a stolen password | Two-factor authentication ([12](#12-add-a-second-factor-and-watch-the-logs)) | Off |\\n| Create accounts in bulk | Auth Codes, IP and email domain allowlists ([4](#4-restrict-operations-with-auth-codes), [7](#7-restrict-registration-by-ip-and-email-domain)) | Registration off |\\n| List usernames through `/wp/v2/users` | Protect Endpoints ([5](#5-enable-endpoint-protection)) | Off |\\n| Spoof an IP address to pass an allowlist | Leave proxy headers untrusted ([6](#6-restrict-auto-login-by-ip-address)) | Proxy headers ignored |\\n\\n## 1. Choose the Right Signing Algorithm\\n\\nThe algorithm you pick determines how tokens are signed and verified.\\n\\n**HMAC algorithms (HS256, HS384, HS512)** use a shared secret. Anyone who knows the secret can both sign and verify tokens. This is fine when only your WordPress server generates and validates tokens.\\n\\n**RSA algorithms (RS256, RS384, RS512)** use a public/private key pair. WordPress signs tokens with the private key; anyone can verify them with the public key - without ever seeing the private key. Choose RS256 when:\\n\\n- A third-party service (external API, CDN, serverless function) needs to verify tokens independently\\n- Your team wants to publish the verification key without exposing signing capability\\n\\nFor most applications, **HS256 is the right default**. If you go this route, the decryption key is everything - treat it accordingly.\\n\\n**Configuration:**\\n```\\nSettings > Simple JWT Login > General > JWT Verification Rules > ELSE\\n```\\n\\n---\\n\\n## 2. Use a Strong Decryption Key\\n\\nThe decryption key is the foundation of your token security. If it\'s weak or guessable, an attacker can forge valid tokens for any user, including administrators.\\n\\nRules for production keys:\\n- **Minimum 32 characters**, ideally 64+\\n- Use a cryptographically random generator, not a human-chosen phrase\\n- Never commit it to version control\\n- Rotate it if you suspect compromise (this invalidates all existing tokens - have a plan for active sessions)\\n\\nGenerate a suitable key from your terminal:\\n\\n```bash\\nopenssl rand -base64 48\\n```\\n\\nTo keep the key out of the database, set the [key source](/docs/configuration#the-else-rule-required-default) to **Code** and define it in `wp-config.php`, for example from an environment variable:\\n\\n```php\\ndefine(\'SIMPLE_JWT_PRIVATE_KEY\', getenv(\'SIMPLE_JWT_PRIVATE_KEY\'));\\n```\\n\\nA database leak then doesn\'t include your signing key. If you enable refresh tokens, give them their own secret: never reuse the signing key.\\n\\n---\\n\\n## 3. Set a Short Token Expiration\\n\\nLong-lived tokens are a liability. If a token is stolen, the attacker has access for its entire lifetime. The shorter the window, the lower the blast radius.\\n\\n**Recommended starting points:**\\n\\n| Application type | Token TTL |\\n|---|---|\\n| Web SPA (frequent use) | 15-60 minutes |\\n| Mobile app | 1-24 hours |\\n| Server-to-server | 5-15 minutes |\\n| Auto-login links (email campaigns) | 10-30 minutes |\\n\\nPair short expiration with a **token refresh** flow so legitimate users aren\'t constantly forced to re-authenticate. Each refresh token works once: a successful refresh invalidates it and returns a new one. The default refresh window is 2 weeks and rolls forward on each use.\\n\\n```\\nSettings > Simple JWT Login > Authentication > JWT Expiration (minutes)\\n```\\n\\n---\\n\\n## 4. Restrict Operations with Auth Codes\\n\\nAuth Codes are optional shared secrets that gate specific plugin operations: authentication, auto-login, user registration, user deletion, and password resets. If an operation requires an Auth Code and the caller doesn\'t provide a valid one, the request is rejected - regardless of whether a valid JWT is present.\\n\\n**Always use Auth Codes for:**\\n\\n- **User registration** - without one, anyone who discovers your endpoint can create WordPress accounts\\n- **User deletion** - even with JWT auth, an extra key adds a meaningful barrier\\n- **Auto-login** - a leaked JWT alone is then not enough to open a WordPress session\\n\\nAuth Code configuration lets you:\\n- Assign each code a **WordPress role** (new users created with that code get that role)\\n- Set an **expiration date** (one-time integrations, temporary access)\\n- Create **multiple codes** for different clients or systems\\n\\n```\\nSettings > Simple JWT Login > Auth Codes\\n```\\n\\nAn Auth Code shipped inside a browser or mobile app is not a secret, because users can extract it. There it only tells clients apart. It is a real barrier only when your own backend makes the call.\\n\\nA practical pattern: one Auth Code per external system that interacts with your API. If a system is compromised, revoke its code without affecting others.\\n\\n---\\n\\n## 5. Enable Endpoint Protection\\n\\nThe WordPress REST API leaks more data than most developers realise. Endpoints like `/wp/v2/users` expose usernames and user IDs publicly by default. Simple JWT Login\'s endpoint protection feature lets you require a valid JWT for any REST route.\\n\\n**Two protection modes:**\\n\\n**Require a valid JWT by default:** Start from a closed position. Every REST request requires a JWT unless the route has a **Public** rule. Recommended for private APIs and admin tools.\\n\\n**Allow access by default:** Only routes with a **JWT required** or **JWT + Roles** rule require authentication. Everything else is public. Suitable for content sites that need public read access but authenticated writes.\\n\\nConfigure per-HTTP-method granularity. A common setup for a content API:\\n\\n| Route | GET | POST | PUT | DELETE |\\n|---|---|---|---|---|\\n| `/wp/v2/posts` | Public | Protected | Protected | Protected |\\n| `/wp/v2/users` | Protected | Protected | Protected | Protected |\\n| `/wp/v2/media` | Public | Protected | Protected | Protected |\\n\\n```\\nSettings > Simple JWT Login > Protect Endpoints\\n```\\n\\nRules are evaluated top to bottom and the first match wins, so put specific rules above broad ones. Since version 4.2.0, rules match the route and method WordPress actually dispatches, so `?_method=` overrides, batch requests, and `_embed` sub-requests can\'t get around them.\\n\\n---\\n\\n## 6. Restrict Auto-Login by IP Address\\n\\nAuto-login opens a full WordPress session, so it deserves extra hardening. If only people on a known network use it, such as an office or a VPN, accept it only from those addresses.\\n\\n```\\nSettings > Simple JWT Login > Autologin > Access Control\\n```\\n\\nA stolen auto-login link then fails from any other network, even if the token hasn\'t expired. The check uses the IP address of whoever opens the link.\\n\\nBehind a reverse proxy, WordPress sees the proxy\'s IP address. Enable [Trust reverse proxy IP headers](/docs/configuration#trust-reverse-proxy-ip-headers) only if a proxy you control appends to `X-Forwarded-For`. On a directly exposed server, clients can forge that header and pass your allowlist.\\n\\nFor email campaigns where users click from arbitrary IPs, leave the restriction disabled and use a short token TTL instead (10-15 minutes). Also enable **safe redirects** under General, so a crafted link can\'t send users to another site.\\n\\n---\\n\\n## 7. Restrict Registration by IP and Email Domain\\n\\nTwo independent controls protect the registration endpoint:\\n\\n**IP allowlist:** Only allow registration requests from known origins - your front-end server, your CI pipeline, etc.\\n\\n```\\nSettings > Simple JWT Login > Register User > Access Control > Allowed IP Addresses\\n```\\n\\n**Email domain allowlist:** Restrict registrations to specific email domains. Useful for internal tools or invite-only platforms where only company email addresses should be allowed.\\n\\n```\\nSettings > Simple JWT Login > Register User > Access Control > Allowed Email Domains\\n```\\n\\nExample: allow only `@yourcompany.com` and `@partner.com` addresses. Registrations with any other address are rejected. The check reads the submitted address and is not proof that the caller owns it.\\n\\n---\\n\\n## 8. Use Token Revocation for Logout and Password Changes\\n\\nJWTs are stateless by design, which means a standard logout (just deleting the client-side token) doesn\'t actually invalidate the token server-side. If the token was copied before logout, it remains valid until expiry.\\n\\nEnable the revoke endpoint to reject a token on the server before it expires:\\n\\n```bash\\ncurl -X POST \\"https://example.com/wp-json/simple-jwt-login/v1/auth/revoke\\" \\\\\\n  -H \\"Authorization: Bearer <token>\\"\\n```\\n\\nThis call revokes the one token you send. To end **all** of a user\'s sessions, turn on **Revoke sessions on password change** (4.2.0, off by default) under Authentication. A password change then deletes the user\'s refresh tokens and rejects every JWT issued before it, including a stolen copy you never saw.\\n\\nRevoking a JWT on logout won\'t help if you don\'t call it, so it\'s worth building into your logout flow as a required step rather than a best-effort one.\\n\\n---\\n\\n## 9. Configure CORS Carefully\\n\\nCORS decides which websites can read your API from a browser. Since version 4.1.1 it also decides which sites the plugin trusts with a JWT:\\n\\n- A header, cookie, or session JWT on a cross-site request is ignored unless **Allow origin** lists that origin.\\n- A `*` entry accepts header JWTs from any origin, but never cookie or session JWTs.\\n- JWTs in the URL or body are not covered by this check.\\n\\n**For production:**\\n\\n1. If your front end is on another domain, enable CORS and list its exact origin.\\n2. Replace `*` with that list.\\n3. If your front end shares your WordPress domain, leave CORS disabled.\\n\\n```\\nSettings > Simple JWT Login > CORS\\n```\\n\\n```\\nAccess-Control-Allow-Origin:  https://yourfrontend.com\\nAccess-Control-Allow-Methods: GET, POST, PUT, DELETE, OPTIONS\\nAccess-Control-Allow-Headers: Content-Type, Authorization\\n```\\n\\nDon\'t move this to Apache or Nginx only: the plugin reads its own **Allow origin** list, so your front end\'s JWTs would be ignored. See [Cross-site requests](/docs/configuration/#cross-site-requests).\\n\\nWhere possible, send tokens as `Authorization: Bearer` and disable the JWT input sources you don\'t use. Tokens in URLs end up in access logs and browser history.\\n\\n---\\n\\n## 10. Disable What You Don\'t Use\\n\\nEvery enabled feature is an attack surface. Simple JWT Login follows a deny-by-default approach, but over time it\'s easy to enable features for testing and forget to turn them off.\\n\\nBefore going to production, audit your settings and disable:\\n\\n- **Auto-login** - if you\'re not using magic links\\n- **Register users** - if registration happens through WordPress\'s built-in flow\\n- **Delete users** - unless your application explicitly needs it\\n- **Reset password** - if you\'re using a separate password management system\\n- **Change password** - same as above\\n\\nThe fewer endpoints active, the smaller the attack surface.\\n\\n---\\n\\n## 11. Bind Tokens to Your Site\\n\\nIf two sites share a signing key, or you accept tokens from an identity provider, a token meant for one app can be valid in another. Since version 4.2.0, set **Expected audience (aud)** so a JWT is only accepted when its `aud` claim contains your value:\\n\\n- For tokens your site signs, set it under **Authentication**. Your site URL is a good value. Users must log in again, because older JWTs have no `aud`.\\n- For tokens from another issuer, set it on the [JWT Verification Rule](/docs/configuration#jwt-verification-rules) - typically your app\'s client ID.\\n\\n---\\n\\n## 12. Add a Second Factor and Watch the Logs\\n\\n**Two-factor authentication.** With the [Two Factor](/docs/integrations/third-party/two-factor/) plugin, `/auth` returns a short-lived interim JWT, and only a valid code turns it into a full JWT. Since version 4.2.0, wrong codes count toward that plugin\'s rate limit, and an interim JWT can be exchanged only once. Users without 2FA configured still log in with a password.\\n\\n**Audit logs.** [Audit logging](/docs/audit-logs/) is off by default. At minimum, log failed logins, failed 2FA codes, user deletions, API key changes, and settings changes.\\n\\n**API keys.** For server-to-server calls, use [API keys](/docs/api-keys/) with only the permissions the caller needs and an expiry date, instead of an administrator\'s JWT.\\n\\n---\\n\\n## Security Hardening Checklist\\n\\nUse this before every production deployment:\\n\\n- [ ] Decryption key is 32+ characters, randomly generated, not in version control\\n- [ ] Algorithm selected matches your use case (HS256 for simple, RS256 for shared verification)\\n- [ ] Every request that carries a JWT uses HTTPS\\n- [ ] Token expiration is set to the shortest practical TTL for your application\\n- [ ] Auth Codes are enabled for registration, deletion, and auto-login\\n- [ ] Each Auth Code is scoped to the minimum required role\\n- [ ] Endpoint protection is configured, and `/wp/v2/users` is not public unless you need it\\n- [ ] Auto-login is limited by IP when used from known networks, and safe redirects are on\\n- [ ] Reverse proxy headers are trusted only behind a proxy you control\\n- [ ] Registration IP and email domain restrictions are configured if applicable\\n- [ ] Your logout flow calls the revoke endpoint\\n- [ ] Revoke sessions on password change is on\\n- [ ] CORS lists exact origins instead of `*`, or is disabled\\n- [ ] Unused JWT input sources are disabled\\n- [ ] Expected audience (`aud`) is set when keys or issuers are shared\\n- [ ] Administrators use 2FA, and audit logging is on\\n- [ ] API keys have minimal permissions and an expiry date\\n- [ ] All unused features (register, delete, auto-login, reset password) are disabled\\n- [ ] Auth Code expiration dates are set for time-limited integrations\\n\\n---\\n\\n## Conclusion\\n\\nSimple JWT Login\'s security posture is only as strong as its configuration. The defaults are safe - nothing is enabled you didn\'t ask for - but a truly hardened production setup requires deliberate choices about algorithms, key strength, Auth Codes, endpoint protection, and CORS.\\n\\nWork through the checklist above before launch and revisit it whenever you enable a new feature. The goal isn\'t paranoia; it\'s ensuring that each exposed capability is intentional, scoped, and monitored.\\n\\nThe [full documentation](/docs/) covers every setting in detail, and the [error codes reference](/docs/error-codes) is useful for debugging unexpected rejections when you tighten restrictions and something stops working."},{"id":"/top-features-simple-jwt-login/","metadata":{"permalink":"/blog/top-features-simple-jwt-login/","editUrl":"https://github.com/simple-jwt-login/website/tree/main/blog/2026-03-10-top-features-simple-jwt-login.md","source":"@site/blog/2026-03-10-top-features-simple-jwt-login.md","title":"5 Standout Features of Simple JWT Login","description":"A deep dive into the five standout features of Simple JWT Login that help you build secure, modern WordPress-powered applications without the boilerplate.","date":"2026-03-10T00:00:00.000Z","tags":[{"inline":false,"label":"Tutorial","permalink":"/blog/tags/tags/tutorial","description":"Tutorials and guides for Simple JWT Login"},{"inline":false,"label":"JWT Authentication","permalink":"/blog/tags/tags/jwt-authentication","description":"Articles about JSON Web Token (JWT) authentication"},{"inline":false,"label":"WordPress Plugin","permalink":"/blog/tags/tags/wordpress-plugin","description":"WordPress plugin tips, features, and usage guides"},{"inline":false,"label":"Security","permalink":"/blog/tags/tags/security","description":"WordPress REST API security and authentication best practices"}],"readingTime":4.64,"hasTruncateMarker":true,"authors":[{"name":"Nicu Micle","title":"Creator of Simple JWT Login","url":"https://github.com/nicumicle","page":{"permalink":"/blog/authors/nicumicle"},"socials":{"x":"https://x.com/nicumicle","github":"https://github.com/nicumicle"},"imageURL":"https://github.com/nicumicle.png","key":"nicumicle"}],"frontMatter":{"title":"5 Standout Features of Simple JWT Login","description":"A deep dive into the five standout features of Simple JWT Login that help you build secure, modern WordPress-powered applications without the boilerplate.","slug":"/top-features-simple-jwt-login/","hide_table_of_contents":false,"authors":"nicumicle","tags":["tutorials","jwt-authentication","wordpress-plugin","security"],"keywords":["Simple JWT Login features","WordPress JWT plugin","auth codes","auto login WordPress","endpoint protection","WordPress REST API authentication"],"image":"/assets/images/social-card.png"},"unlisted":false,"prevItem":{"title":"JWT Security Hardening Guide","permalink":"/blog/simple-jwt-login-security-hardening/"},"nextItem":{"title":"Authenticate WPGraphQL Requests with JWT","permalink":"/blog/wpgraphql-jwt-authentication/"}},"content":"JWT authentication for WordPress doesn\'t have to be complicated. Simple JWT Login has been quietly powering headless WordPress sites, mobile backends, and SPA integrations for years - and it does so with a level of configurability that most teams never fully explore.\\n\\nHere are the five most powerful features, and why they matter for real-world projects.\\n\\n\x3c!--truncate--\x3e\\n\\n## 1. Auth Codes - Fine-Grained API Key Control\\n\\nMost JWT plugins treat authentication as binary: you either have a valid token or you don\'t. Simple JWT Login goes further with **Auth Codes** - optional API keys that gate specific operations like registration, auto-login, or user deletion.\\n\\nEach Auth Code can be scoped to a specific action, assigned a WordPress user role, and even given an expiration date. This means you can issue a time-limited code to an external system for a batch user import, let it expire automatically, and never worry about revoking it manually.\\n\\n```bash\\n# Register a user only when a valid auth_code is present\\ncurl -X POST \\"https://example.com/wp-json/simple-jwt-login/v1/users\\" \\\\\\n  -H \\"Content-Type: application/json\\" \\\\\\n  -d \'{\\n    \\"email\\": \\"jane@example.com\\",\\n    \\"password\\": \\"securepassword\\",\\n    \\"auth_code\\": \\"YOUR_AUTH_CODE\\"\\n  }\'\\n```\\n\\nThe practical use case: you\'re integrating a third-party signup funnel. You issue it a restricted Auth Code that only allows registration, with the `subscriber` role. The funnel can create users - nothing else. That\'s a meaningful security boundary with zero custom code.\\n\\n---\\n\\n## 2. Auto-Login with Dynamic Redirects\\n\\nAutologin is the feature that consistently surprises people. Send a user a URL with a valid JWT, and Simple JWT Login authenticates them silently and redirects them wherever you need - no password prompt, no login page friction.\\n\\nWhat makes it genuinely powerful is the **redirect URL variables**. Your redirect target can be dynamically built using the authenticated user\'s data:\\n\\n| Variable | Value |\\n|---|---|\\n| `{{user_id}}` | WordPress user ID |\\n| `{{user_email}}` | User\'s email address |\\n| `{{user_login}}` | Username |\\n| `{{user_first_name}}` | First name |\\n| `{{site_url}}` | Your site\'s base URL |\\n\\n```\\nhttps://example.com/?JWT=<token>&redirectUrl={{site_url}}/dashboard/?uid={{user_id}}\\n```\\n\\nReal-world application: email marketing campaigns. Generate a signed JWT per subscriber, embed it in your campaign link, and drop users directly into their account dashboard - already logged in. The MailPoet add-on takes this even further by providing a shortcode that generates these links automatically inside your email templates.\\n\\nYou also get a **fail-safe redirect** for invalid or expired tokens, so users with stale links don\'t hit a blank error page.\\n\\n---\\n\\n## 3. Endpoint Protection - Protect Your Entire REST API\\n\\nWordPress\'s REST API is powerful, but by default it exposes a lot of data publicly. Simple JWT Login\'s **Endpoint Protection** feature lets you put a JWT requirement in front of any REST route - or all of them at once.\\n\\nTwo modes are available:\\n\\n- **Protect all, whitelist exceptions**: Every REST request must carry a valid JWT unless the route is explicitly whitelisted.\\n- **Protect only listed routes**: Specific sensitive endpoints require a JWT; everything else remains public.\\n\\nBoth modes support per-HTTP-method granularity. You might want `GET /wp-json/wp/v2/posts` to stay public while `POST` and `DELETE` on the same route require authentication. That\'s one configuration, no custom middleware.\\n\\n```\\nProtected:  POST   /wp-json/wp/v2/posts\\nProtected:  DELETE /wp-json/wp/v2/posts/{id}\\nPublic:     GET    /wp-json/wp/v2/posts\\n```\\n\\nRoute matching supports both exact paths and prefix patterns (`starts-with`), which makes it easy to protect entire feature namespaces - for example, locking down everything under `/wp-json/woocommerce/` with a single rule.\\n\\n---\\n\\n## 4. WordPress Hooks & Filters - Deep Customization Without Forking\\n\\nSimple JWT Login ships with **16 hooks** that let you tap into every significant operation. This is the feature that separates it from simpler JWT plugins and makes it production-grade for complex applications.\\n\\nA few practical examples:\\n\\n**Add custom claims to the JWT payload:**\\n\\n```php\\nadd_filter(\'simple_jwt_login_jwt_payload\', function($payload, $user) {\\n    $payload[\'role\']       = implode(\',\', $user->roles);\\n    $payload[\'company_id\'] = get_user_meta($user->ID, \'company_id\', true);\\n    return $payload;\\n}, 10, 2);\\n```\\n\\n**Send a welcome email after registration:**\\n\\n```php\\nadd_action(\'simple_jwt_login_register_hook\', function($user, $request) {\\n    wp_mail(\\n        $user->user_email,\\n        \'Welcome aboard!\',\\n        \'Your account is ready. Log in at \' . get_site_url()\\n    );\\n}, 10, 2);\\n```\\n\\n**Customize the authentication response:**\\n\\n```php\\nadd_filter(\'simple_jwt_login_response_auth\', function($response, $user, $jwt) {\\n    $response[\'avatar_url\'] = get_avatar_url($user->ID);\\n    $response[\'display_name\'] = $user->display_name;\\n    return $response;\\n}, 10, 3);\\n```\\n\\nNo monkey-patching, no plugin forks - just clean WordPress action and filter hooks that survive updates.\\n\\n---\\n\\n## 5. Multiple JWT Delivery Methods\\n\\nAPIs get consumed in many different environments: browser SPAs, mobile apps, server-to-server calls, legacy form-based flows. Simple JWT Login supports **five distinct ways** to pass a JWT, so you\'re never forced to restructure your client to match the plugin.\\n\\n| Method | How to use |\\n|---|---|\\n| Authorization header | `Authorization: Bearer <token>` |\\n| Query parameter | `?JWT=<token>` |\\n| Request body | `{\\"JWT\\": \\"<token>\\"}` |\\n| Cookie | `simple-jwt-login-token` |\\n| Session | `$_SESSION[\'simple-jwt-login-token\']` |\\n\\nThe plugin processes them in a defined priority order (Header > Cookie > Session > Request body), so if multiple sources are present, behavior is predictable.\\n\\nFor browser-based apps that need to avoid storing tokens in `localStorage`, the cookie delivery method is especially useful - pair it with an `HttpOnly` cookie set server-side and you have a solid defense against XSS token theft.\\n\\n---\\n\\n## Conclusion\\n\\nSimple JWT Login earns its place in a production WordPress stack because it\'s thoughtfully layered. You can use it at face value - just generate and validate tokens - or you can reach into Auth Codes, hooks, endpoint protection, and dynamic redirects to build something genuinely sophisticated.\\n\\nThe plugin is free, actively maintained, and the [full documentation](/docs/) covers every configuration option in detail. If you\'re building anything beyond a basic WordPress blog, it\'s worth an afternoon to set up properly."},{"id":"/wpgraphql-jwt-authentication/","metadata":{"permalink":"/blog/wpgraphql-jwt-authentication/","editUrl":"https://github.com/simple-jwt-login/website/tree/main/blog/2026-03-10-wpgraphql-jwt-authentication.md","source":"@site/blog/2026-03-10-wpgraphql-jwt-authentication.md","title":"Authenticate WPGraphQL Requests with JWT","description":"A step-by-step guide to securing your WPGraphQL API with JWTs - setup, authenticated queries, mutations, and token handling.","date":"2026-03-10T00:00:00.000Z","tags":[{"inline":false,"label":"Tutorial","permalink":"/blog/tags/tags/tutorial","description":"Tutorials and guides for Simple JWT Login"},{"inline":false,"label":"WPGraphQL","permalink":"/blog/tags/tags/wpgraphql","description":"Integrating Simple JWT Login with WPGraphQL"},{"inline":false,"label":"JWT Authentication","permalink":"/blog/tags/tags/jwt-authentication","description":"Articles about JSON Web Token (JWT) authentication"},{"inline":false,"label":"Headless WordPress","permalink":"/blog/tags/tags/headless-wordpress","description":"Articles about headless WordPress architecture and JWT authentication"}],"readingTime":5.41,"hasTruncateMarker":true,"authors":[{"name":"Nicu Micle","title":"Creator of Simple JWT Login","url":"https://github.com/nicumicle","page":{"permalink":"/blog/authors/nicumicle"},"socials":{"x":"https://x.com/nicumicle","github":"https://github.com/nicumicle"},"imageURL":"https://github.com/nicumicle.png","key":"nicumicle"}],"frontMatter":{"title":"Authenticate WPGraphQL Requests with JWT","description":"A step-by-step guide to securing your WPGraphQL API with JWTs - setup, authenticated queries, mutations, and token handling.","slug":"/wpgraphql-jwt-authentication/","hide_table_of_contents":false,"authors":"nicumicle","tags":["tutorials","wpgraphql","jwt-authentication","headless-wordpress"],"keywords":["WPGraphQL JWT authentication","WordPress GraphQL auth","Simple JWT Login WPGraphQL","GraphQL bearer token","headless WordPress GraphQL","Apollo Client WordPress"],"image":"/assets/images/social-card.png"},"unlisted":false,"prevItem":{"title":"5 Standout Features of Simple JWT Login","permalink":"/blog/top-features-simple-jwt-login/"},"nextItem":{"title":"Export-Import Add-on Released","permalink":"/blog/simple-jwt-login-export-import-add-on/"}},"content":"GraphQL and headless WordPress are a natural match. WPGraphQL gives you a flexible, typed query layer over all your WordPress data. But like the REST API, it\'s unauthenticated by default - anyone can query it. Simple JWT Login solves that.\\n\\nIn this guide I\'ll walk through connecting Simple JWT Login to WPGraphQL so your GraphQL operations can carry a JWT, granting access to protected data and enabling authenticated mutations like creating posts or updating user profiles.\\n\\n\x3c!--truncate--\x3e\\n\\n## Prerequisites\\n\\nYou\'ll need two plugins installed and active:\\n\\n- **WPGraphQL** - available at [wpgraphql.com](https://www.wpgraphql.com)\\n- **Simple JWT Login** - available in the [WordPress plugin repository](https://wordpress.org/plugins/simple-jwt-login/)\\n\\nNo additional bridge plugin is required. Simple JWT Login\'s WPGraphQL integration is built in.\\n\\n---\\n\\n## How It Works\\n\\nThe integration is straightforward: Simple JWT Login generates and validates JWTs using its standard `/auth` endpoint. When a request hits the WPGraphQL endpoint (`/wp-json/graphql` or `/graphql`), Simple JWT Login intercepts it, validates the bearer token, and - if valid - sets the current WordPress user context before WPGraphQL resolves the query.\\n\\nFrom WPGraphQL\'s perspective, the request simply arrives as an authenticated WordPress user. Every resolver that checks `current_user_can()` or relies on `wp_get_current_user()` works exactly as it would in a browser session.\\n\\n---\\n\\n## Step 1 - Configure Simple JWT Login\\n\\nNavigate to **Simple JWT Login** in your WordPress admin. The core settings you need:\\n\\n**General tab:**\\n- Set a strong **JWT Decryption Key**\\n- Choose **HS256** as your algorithm (or RS256 for asymmetric setups)\\n- Set a sensible **JWT expiration** (for example, 3600 seconds / 1 hour)\\n\\n**WPGraphQL tab:**\\n\\nEnable the WPGraphQL integration:\\n\\n```\\nSettings > Simple JWT Login > WPGraphQL > Enable WPGraphQL authentication\\n```\\n\\nThat\'s the only required toggle. The plugin now validates JWTs on every request to your GraphQL endpoint.\\n\\n---\\n\\n## Step 2 - Obtain a JWT\\n\\nUse the standard auth endpoint to get a token:\\n\\n```bash\\ncurl -X POST \\"https://example.com/wp-json/simple-jwt-login/v1/auth\\" \\\\\\n  -H \\"Content-Type: application/json\\" \\\\\\n  -d \'{\\n    \\"email\\": \\"editor@example.com\\",\\n    \\"password\\": \\"their_password\\"\\n  }\'\\n```\\n\\nResponse:\\n\\n```json\\n{\\n  \\"success\\": true,\\n  \\"data\\": {\\n    \\"jwt\\": \\"eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9...\\"\\n  }\\n}\\n```\\n\\n---\\n\\n## Step 3 - Make Authenticated GraphQL Queries\\n\\nPass the token as a bearer token in the `Authorization` header on every GraphQL request:\\n\\n```bash\\ncurl -X POST \\"https://example.com/graphql\\" \\\\\\n  -H \\"Content-Type: application/json\\" \\\\\\n  -H \\"Authorization: Bearer eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9...\\" \\\\\\n  -d \'{\\n    \\"query\\": \\"{ viewer { id name email roles { nodes { name } } } }\\"\\n  }\'\\n```\\n\\nWithout the token, `viewer` returns `null`. With it, you get the full authenticated user object:\\n\\n```json\\n{\\n  \\"data\\": {\\n    \\"viewer\\": {\\n      \\"id\\": \\"dXNlcjoyNQ==\\",\\n      \\"name\\": \\"Jane Editor\\",\\n      \\"email\\": \\"editor@example.com\\",\\n      \\"roles\\": {\\n        \\"nodes\\": [{ \\"name\\": \\"editor\\" }]\\n      }\\n    }\\n  }\\n}\\n```\\n\\n---\\n\\n## Step 4 - Authenticated Mutations\\n\\nThis is where the integration becomes genuinely useful. Many WPGraphQL mutations require an authenticated user. Creating a post, for example:\\n\\n```bash\\ncurl -X POST \\"https://example.com/graphql\\" \\\\\\n  -H \\"Content-Type: application/json\\" \\\\\\n  -H \\"Authorization: Bearer eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9...\\" \\\\\\n  -d \'{\\n    \\"query\\": \\"mutation CreatePost($input: CreatePostInput!) { createPost(input: $input) { post { id title status } } }\\",\\n    \\"variables\\": {\\n      \\"input\\": {\\n        \\"title\\": \\"My First API Post\\",\\n        \\"content\\": \\"Written via GraphQL with JWT auth.\\",\\n        \\"status\\": \\"PUBLISH\\",\\n        \\"clientMutationId\\": \\"create-post-1\\"\\n      }\\n    }\\n  }\'\\n```\\n\\nWithout authentication, this mutation returns a permission error. With a valid JWT for a user who has the `editor` or `administrator` role, it succeeds and returns the created post.\\n\\n---\\n\\n## Using the Integration in a JavaScript Client\\n\\nIn a Next.js or React app, you\'ll typically store the JWT after login and attach it to every GraphQL request. Here\'s how that looks with a simple fetch-based client:\\n\\n```js\\nconst GQL_ENDPOINT = \'https://example.com/graphql\';\\n\\nasync function graphqlRequest(query, variables = {}, token = null) {\\n  const headers = { \'Content-Type\': \'application/json\' };\\n  if (token) {\\n    headers[\'Authorization\'] = `Bearer ${token}`;\\n  }\\n\\n  const response = await fetch(GQL_ENDPOINT, {\\n    method: \'POST\',\\n    headers,\\n    body: JSON.stringify({ query, variables }),\\n  });\\n\\n  return response.json();\\n}\\n\\n// Login and get a token\\nasync function login(email, password) {\\n  const response = await fetch(\\n    \'https://example.com/wp-json/simple-jwt-login/v1/auth\',\\n    {\\n      method: \'POST\',\\n      headers: { \'Content-Type\': \'application/json\' },\\n      body: JSON.stringify({ email, password }),\\n    }\\n  );\\n  const data = await response.json();\\n  return data.data.jwt;\\n}\\n\\n// Example usage\\nconst token = await login(\'editor@example.com\', \'password\');\\n\\nconst { data } = await graphqlRequest(\\n  `{ viewer { name email } }`,\\n  {},\\n  token\\n);\\n\\nconsole.log(data.viewer); // { name: \'Jane Editor\', email: \'editor@example.com\' }\\n```\\n\\nIf you\'re using Apollo Client, set the token in your auth link:\\n\\n```js\\nimport { ApolloClient, InMemoryCache, createHttpLink } from \'@apollo/client\';\\nimport { setContext } from \'@apollo/client/link/context\';\\n\\nconst httpLink = createHttpLink({ uri: \'https://example.com/graphql\' });\\n\\nconst authLink = setContext((_, { headers }) => {\\n  const token = localStorage.getItem(\'jwt\'); // or however you store it\\n  return {\\n    headers: {\\n      ...headers,\\n      authorization: token ? `Bearer ${token}` : \'\',\\n    },\\n  };\\n});\\n\\nconst client = new ApolloClient({\\n  link: authLink.concat(httpLink),\\n  cache: new InMemoryCache(),\\n});\\n```\\n\\n---\\n\\n## Enriching Queries with Custom JWT Claims\\n\\nSometimes you want to avoid an extra `viewer` query on page load by embedding user metadata directly in the token. Use the `simple_jwt_login_jwt_payload` filter to add whatever your front-end needs:\\n\\n```php\\nadd_filter(\'simple_jwt_login_jwt_payload\', function($payload, $user) {\\n    $payload[\'wp_roles\']     = $user->roles;\\n    $payload[\'display_name\'] = $user->display_name;\\n    $payload[\'avatar_url\']   = get_avatar_url($user->ID, [\'size\' => 48]);\\n    return $payload;\\n}, 10, 2);\\n```\\n\\nYour Apollo or fetch client can decode the JWT (it\'s just base64) and read these values without any extra network request:\\n\\n```js\\nfunction decodeJwtPayload(token) {\\n  const base64 = token.split(\'.\')[1].replace(/-/g, \'+\').replace(/_/g, \'/\');\\n  return JSON.parse(atob(base64));\\n}\\n\\nconst payload = decodeJwtPayload(token);\\nconsole.log(payload.display_name); // \\"Jane Editor\\"\\nconsole.log(payload.wp_roles);     // [\\"editor\\"]\\n```\\n\\n---\\n\\n## Protecting the GraphQL Endpoint Itself\\n\\nBy default, WPGraphQL allows unauthenticated introspection queries, which exposes your full schema to anyone. You can lock this down at two levels:\\n\\n**WPGraphQL side:** Disable public introspection in WPGraphQL settings.\\n\\n**Simple JWT Login side:** Add the GraphQL endpoint to your protected routes:\\n\\n```\\nSettings > Simple JWT Login > Protect Endpoints\\nAdd route: /graphql\\nMethods: GET, POST\\n```\\n\\nThis ensures every GraphQL request - including introspection - must carry a valid JWT. Ideal for private internal APIs.\\n\\n---\\n\\n## Token Refresh for Long-Running Sessions\\n\\nGraphQL apps often run as SPAs where the user stays on the page for extended periods. Implement proactive token refresh to avoid mid-session `401` errors:\\n\\n```js\\nfunction isTokenExpiringSoon(token, bufferSeconds = 300) {\\n  const { exp } = decodeJwtPayload(token);\\n  return (exp - bufferSeconds) < (Date.now() / 1000);\\n}\\n\\nasync function refreshToken(currentToken) {\\n  const response = await fetch(\\n    \'https://example.com/wp-json/simple-jwt-login/v1/auth/refresh\',\\n    {\\n      method: \'POST\',\\n      headers: { \'Content-Type\': \'application/json\' },\\n      body: JSON.stringify({ JWT: currentToken }),\\n    }\\n  );\\n  const data = await response.json();\\n  return data.data.jwt;\\n}\\n\\n// Before each GraphQL request:\\nif (isTokenExpiringSoon(storedToken)) {\\n  storedToken = await refreshToken(storedToken);\\n  // persist updated token\\n}\\n```\\n\\n---\\n\\n## Conclusion\\n\\nSimple JWT Login and WPGraphQL complement each other cleanly. WPGraphQL handles the query layer; Simple JWT Login handles identity. The integration requires no extra plugins, just a single settings toggle, and the result is a fully authenticated GraphQL API that honours WordPress\'s existing user roles and capabilities.\\n\\nFrom there, the hooks system gives you room to customize the JWT payload, and the endpoint protection feature lets you lock down the GraphQL route to authenticated traffic only. It\'s a solid foundation for any headless WordPress application built on GraphQL."},{"id":"/simple-jwt-login-export-import-add-on/","metadata":{"permalink":"/blog/simple-jwt-login-export-import-add-on/","editUrl":"https://github.com/simple-jwt-login/website/tree/main/blog/2023-03-04-import-export.md","source":"@site/blog/2023-03-04-import-export.md","title":"Export-Import Add-on Released","description":"The Export-Import add-on for Simple JWT Login lets you copy your full configuration - Auth Codes, protection rules, and settings - between WordPress sites.","date":"2023-03-04T00:00:00.000Z","tags":[{"inline":false,"label":"Release","permalink":"/blog/tags/tags/release","description":"Plugin Releases"},{"inline":false,"label":"Add-on","permalink":"/blog/tags/tags/add-on","description":"Plugin Addons"}],"readingTime":0.51,"hasTruncateMarker":true,"authors":[{"name":"Nicu Micle","title":"Creator of Simple JWT Login","url":"https://github.com/nicumicle","page":{"permalink":"/blog/authors/nicumicle"},"socials":{"x":"https://x.com/nicumicle","github":"https://github.com/nicumicle"},"imageURL":"https://github.com/nicumicle.png","key":"nicumicle"}],"frontMatter":{"title":"Export-Import Add-on Released","description":"The Export-Import add-on for Simple JWT Login lets you copy your full configuration - Auth Codes, protection rules, and settings - between WordPress sites.","keywords":["export import","WordPress plugin","migration","staging","Auth Codes"],"slug":"/simple-jwt-login-export-import-add-on/","hide_table_of_contents":false,"authors":"nicumicle","tags":["release","add-on"],"image":"/assets/images/social-card.png"},"unlisted":false,"prevItem":{"title":"Authenticate WPGraphQL Requests with JWT","permalink":"/blog/wpgraphql-jwt-authentication/"},"nextItem":{"title":"Using the JavaScript SDK in a React App","permalink":"/blog/javascript-sdk-usage-react/"}},"content":"The `beta` version of the Export-Import add-on is out. [Download it](https://github.com/simple-jwt-login/export-import/archive/refs/heads/master.zip) for **free** from GitHub and try it.\\n\\n\x3c!--truncate--\x3e\\n\\n## Installation\\n\\n1. Download the add-on from [GitHub](https://github.com/simple-jwt-login/export-import/).\\n2. Upload the zip file to WordPress.\\n3. Activate the plugin.\\n4. Export or import your settings.\\n\\nSee the [Export-Import add-on documentation](/docs/export-import/) for details.\\n\\n## Feedback\\n\\nIf you find a bug or have an idea for an improvement, please [open an issue](https://github.com/simple-jwt-login/export-import/issues)."},{"id":"/javascript-sdk-usage-react/","metadata":{"permalink":"/blog/javascript-sdk-usage-react/","editUrl":"https://github.com/simple-jwt-login/website/tree/main/blog/2022-10-27-how_to_use_the_js_sdk.md","source":"@site/blog/2022-10-27-how_to_use_the_js_sdk.md","title":"Using the JavaScript SDK in a React App","description":"A real-world walkthrough of using the Simple JWT Login JavaScript SDK inside a React app to authenticate against the WordPress REST API.","date":"2022-10-27T00:00:00.000Z","tags":[{"inline":false,"label":"Tutorial","permalink":"/blog/tags/tags/tutorial","description":"Tutorials and guides for Simple JWT Login"}],"readingTime":3.21,"hasTruncateMarker":true,"authors":[{"name":"Nicu Micle","title":"Creator of Simple JWT Login","url":"https://github.com/nicumicle","page":{"permalink":"/blog/authors/nicumicle"},"socials":{"x":"https://x.com/nicumicle","github":"https://github.com/nicumicle"},"imageURL":"https://github.com/nicumicle.png","key":"nicumicle"}],"frontMatter":{"title":"Using the JavaScript SDK in a React App","description":"A real-world walkthrough of using the Simple JWT Login JavaScript SDK inside a React app to authenticate against the WordPress REST API.","keywords":["JavaScript SDK","React","JWT authentication","WordPress REST API","headless WordPress"],"slug":"/javascript-sdk-usage-react/","hide_table_of_contents":false,"authors":"nicumicle","tags":["tutorials"],"image":"/assets/images/social-card.png"},"unlisted":false,"prevItem":{"title":"Export-Import Add-on Released","permalink":"/blog/simple-jwt-login-export-import-add-on/"},"nextItem":{"title":"CORS Setup on Apache Server","permalink":"/blog/cors-setup-apache/"}},"content":":::warning Updated November 2026\\nThis post was written for Simple JWT Login 3.x and SDK version 0.1. The steps below are updated for current tools: [Vite](https://vite.dev/) replaces Create React App, which is deprecated. The SDK\'s `registerUser()` call works with plugin 4.x, but its `refreshToken()` method still uses the 3.x refresh flow. For complete, current examples, see the [React code example](/docs/code-examples/react).\\n:::\\n\\nThe first version of the Simple JWT Login JavaScript SDK is out. Install it with `npm`:\\n\\n```bash\\nnpm install simple-jwt-login\\n```\\n\\nor with `yarn`:\\n\\n```bash\\nyarn add simple-jwt-login\\n```\\n\x3c!--truncate--\x3e\\n\\n## Set Up the Project\\n\\nCreate a React project in the `my-app` folder with Vite:\\n\\n```bash\\nnpm create vite@latest my-app -- --template react\\n```\\n\\nThen go to the new folder, install the dependencies, and start the development server:\\n\\n```bash\\ncd my-app\\nnpm install\\nnpm run dev\\n```\\n\\nVite prints a local URL, such as `http://localhost:5173`. Open it in your browser to see the starter app.\\n\\n## Install the SDK\\n\\nIn the `my-app` folder, run:\\n\\n```bash\\nnpm install simple-jwt-login\\n```\\n\\nThe package now appears under `dependencies` in `package.json`, and the app can import it.\\n\\n## Create a Register Form\\n\\nReplace the content of `src/App.jsx` with a form that has two inputs, for the email and the password, and a **Register User** button. The `handleClick` function runs when the button is clicked:\\n\\n```jsx\\nimport { useRef } from \'react\';\\n\\nfunction App() {\\n  const emailRef = useRef(null);\\n  const passwordRef = useRef(null);\\n\\n  function handleClick() {\\n    // The next section adds the SDK call here.\\n  }\\n\\n  return (\\n    <div>\\n      <label>\\n        Email: <input ref={emailRef} type=\\"email\\" name=\\"email\\" />\\n      </label>\\n      <label>\\n        Password: <input ref={passwordRef} type=\\"password\\" name=\\"password\\" />\\n      </label>\\n      <button onClick={handleClick}>Register User</button>\\n    </div>\\n  );\\n}\\n\\nexport default App;\\n```\\n\\nThe page now shows the register form:\\n\\n![React register form](/assets/images/blog/react_register_form.png \\"React Register Form\\")\\n\\n## Call the SDK\\n\\nImport the SDK at the top of `src/App.jsx`:\\n\\n```jsx\\nimport { SimpleJwtLogin } from \'simple-jwt-login\';\\n```\\n\\nCreate a client with the address of your WordPress site and the route namespace. This example uses a local WordPress site at `http://localhost:88` with the default namespace, `/simple-jwt-login/v1`:\\n\\n```jsx\\nconst simpleJwtLogin = new SimpleJwtLogin(\'http://localhost:88\', \'/simple-jwt-login/v1\');\\n```\\n\\nThe SDK methods don\'t return the response. Instead, they pass it to the function you register with `withCallback()`, together with the HTTP status code. Update `handleClick` to read the inputs and register the user:\\n\\n```jsx\\nfunction handleClick() {\\n  const simpleJwtLogin = new SimpleJwtLogin(\'http://localhost:88\', \'/simple-jwt-login/v1\');\\n\\n  simpleJwtLogin.withCallback((response, status) => {\\n    console.log(status, response);\\n  });\\n\\n  simpleJwtLogin.registerUser({\\n    email: emailRef.current.value,\\n    password: passwordRef.current.value,\\n  });\\n}\\n```\\n\\nTurn on **User Registration** under **Settings \u2192 Simple JWT Login \u2192 Register User** first. If **Require Authentication Code** is on, pass the code as the second argument: `registerUser(params, \\"your-auth-code\\")`. Because the app runs on a different origin than WordPress, also add `http://localhost:5173` to **Allow origin** in the [CORS](/docs/cors/) settings.\\n\\n## Full Code\\n\\n```jsx\\nimport { useRef } from \'react\';\\nimport { SimpleJwtLogin } from \'simple-jwt-login\';\\n\\nfunction App() {\\n  const emailRef = useRef(null);\\n  const passwordRef = useRef(null);\\n\\n  function handleClick() {\\n    const simpleJwtLogin = new SimpleJwtLogin(\'http://localhost:88\', \'/simple-jwt-login/v1\');\\n\\n    simpleJwtLogin.withCallback((response, status) => {\\n      console.log(status, response);\\n    });\\n\\n    simpleJwtLogin.registerUser({\\n      email: emailRef.current.value,\\n      password: passwordRef.current.value,\\n    });\\n  }\\n\\n  return (\\n    <div>\\n      <label>\\n        Email: <input ref={emailRef} type=\\"email\\" name=\\"email\\" />\\n      </label>\\n      <label>\\n        Password: <input ref={passwordRef} type=\\"password\\" name=\\"password\\" />\\n      </label>\\n      <button onClick={handleClick}>Register User</button>\\n    </div>\\n  );\\n}\\n\\nexport default App;\\n```\\n\\nFill in the form and click **Register User**. The browser console shows the status code and the new user:\\n\\n```json\\n{\\n  \\"success\\": true,\\n  \\"data\\": {\\n    \\"id\\": 1,\\n    \\"login\\": \\"myuser\\",\\n    \\"email\\": \\"myuser@example.com\\",\\n    \\"roles\\": [\\"subscriber\\"]\\n  }\\n}\\n```\\n\\nSee [Register User](/docs/register-user/) for every field in the response.\\n\\n## Conclusion\\n\\nThe SDK lets you call WordPress from JavaScript with a few lines of code. It builds the endpoint URLs and picks the request methods, so you only need to send the required parameters."},{"id":"/cors-setup-apache/","metadata":{"permalink":"/blog/cors-setup-apache/","editUrl":"https://github.com/simple-jwt-login/website/tree/main/blog/2022-10-26-CORS-setup.md","source":"@site/blog/2022-10-26-CORS-setup.md","title":"CORS Setup on Apache Server","description":"Step-by-step guide to configuring CORS on an Apache server so your headless frontend can call the WordPress REST API with Simple JWT Login.","date":"2022-10-26T00:00:00.000Z","tags":[{"inline":false,"label":"Tutorial","permalink":"/blog/tags/tags/tutorial","description":"Tutorials and guides for Simple JWT Login"}],"readingTime":2.12,"hasTruncateMarker":true,"authors":[{"name":"Nicu Micle","title":"Creator of Simple JWT Login","url":"https://github.com/nicumicle","page":{"permalink":"/blog/authors/nicumicle"},"socials":{"x":"https://x.com/nicumicle","github":"https://github.com/nicumicle"},"imageURL":"https://github.com/nicumicle.png","key":"nicumicle"}],"frontMatter":{"title":"CORS Setup on Apache Server","description":"Step-by-step guide to configuring CORS on an Apache server so your headless frontend can call the WordPress REST API with Simple JWT Login.","keywords":["CORS","Apache","WordPress REST API","headless WordPress","JWT authentication"],"slug":"/cors-setup-apache/","hide_table_of_contents":false,"authors":"nicumicle","tags":["tutorials"],"image":"/assets/images/social-card.png"},"unlisted":false,"prevItem":{"title":"Using the JavaScript SDK in a React App","permalink":"/blog/javascript-sdk-usage-react/"},"nextItem":{"title":"JavaScript SDK Released","permalink":"/blog/simple-jwt-login-js-sdk-0.1.1/"}},"content":":::warning Updated November 2026\\nThis post was written for Simple JWT Login 3.x. On current versions, set CORS in the plugin under **Settings \u2192 Simple JWT Login \u2192 CORS** instead of Apache - see [CORS](/docs/cors/). Since version 4.1.1, a browser app on another domain can authenticate with a JWT only when its origin is listed in **Allow origin**, and a `*` origin never trusts cookie or session JWTs. Use the Apache setup below only for routes the plugin doesn\'t handle.\\n:::\\n\\nBrowsers block JavaScript calls from one domain to another unless the server allows them with [CORS](https://en.wikipedia.org/wiki/Cross-origin_resource_sharing) headers. This tutorial shows how to add those headers on an Apache server.\\n\\n\x3c!--truncate--\x3e\\n## How to Spot a CORS Issue\\n\\nCall your endpoint from the browser with JavaScript. A CORS issue shows an error like this in the console:\\n\\n```\\nAccess to ... at \'http://....\' from origin \'http://..\' has been blocked\\nby CORS policy: Response to preflight request doesn\'t pass access control\\ncheck: No \'Access-Control-Allow-Origin\' header is present in the requested resource.\\n```\\n\\n## Fix It in Apache\\n\\nConnect to your server over SSH and enable the Apache `headers` module:\\n\\n```bash\\nsudo a2enmod headers\\n```\\n\\nApache confirms it:\\n\\n```\\nEnabling module headers.\\nTo activate the new configuration, you need to run:\\n  service apache2 restart\\n```\\n\\nIf the module is already on, the output is `Module headers already enabled`.\\n\\nNext, open the Apache configuration file:\\n\\n```bash\\nsudo vi /etc/apache2/apache2.conf\\n```\\n\\nIf your site runs from `/var/www/html`, find the `<Directory \\"/var/www/html\\">` block, or add it at the end of the file. Replace `https://app.example.com` with the origin of your front-end:\\n\\n```\\n<Directory \\"/var/www/html\\">\\n    AllowOverride All\\n    Require all granted\\n\\n    Header set Access-Control-Allow-Origin \\"https://app.example.com\\"\\n    Header set Access-Control-Allow-Methods \\"GET, POST, PUT, PATCH, DELETE, OPTIONS\\"\\n    Header set Access-Control-Allow-Headers \\"x-requested-with, Content-Type, origin, authorization, accept\\"\\n    Header set Access-Control-Expose-Headers \\"Location\\"\\n    Header set Access-Control-Max-Age \\"600\\"\\n    Header merge Vary \\"Origin\\"\\n\\n    RewriteEngine On\\n    RewriteCond %{REQUEST_METHOD} OPTIONS\\n    RewriteRule ^(.*)$ $1 [R=200,L]\\n</Directory>\\n```\\n\\nKeep `AllowOverride All`: WordPress needs its `.htaccess` file for pretty permalinks and the `/wp-json/` routes. Avoid `Access-Control-Allow-Origin \\"*\\"`, because it lets any website call your API from a visitor\'s browser.\\n\\nDon\'t set the same headers in Apache and in the plugin\'s CORS settings. Browsers reject a response that has two `Access-Control-Allow-Origin` headers.\\n\\nRestart Apache to apply the changes:\\n\\n```bash\\nsudo service apache2 restart\\n```\\n\\nYour front-end can now call the server from the browser."},{"id":"/simple-jwt-login-js-sdk-0.1.1/","metadata":{"permalink":"/blog/simple-jwt-login-js-sdk-0.1.1/","editUrl":"https://github.com/simple-jwt-login/website/tree/main/blog/2022-10-25-release-js-sdk.md","source":"@site/blog/2022-10-25-release-js-sdk.md","title":"JavaScript SDK Released","description":"The official Simple JWT Login JavaScript SDK is now available, making it easy to authenticate against the WordPress REST API from JS apps.","date":"2022-10-25T00:00:00.000Z","tags":[{"inline":false,"label":"Release","permalink":"/blog/tags/tags/release","description":"Plugin Releases"}],"readingTime":1.09,"hasTruncateMarker":true,"authors":[{"name":"Nicu Micle","title":"Creator of Simple JWT Login","url":"https://github.com/nicumicle","page":{"permalink":"/blog/authors/nicumicle"},"socials":{"x":"https://x.com/nicumicle","github":"https://github.com/nicumicle"},"imageURL":"https://github.com/nicumicle.png","key":"nicumicle"}],"frontMatter":{"title":"JavaScript SDK Released","description":"The official Simple JWT Login JavaScript SDK is now available, making it easy to authenticate against the WordPress REST API from JS apps.","keywords":["JavaScript SDK","JWT authentication","WordPress REST API","headless WordPress"],"slug":"/simple-jwt-login-js-sdk-0.1.1/","hide_table_of_contents":false,"authors":"nicumicle","tags":["release"],"image":"/assets/images/social-card.png"},"unlisted":false,"prevItem":{"title":"CORS Setup on Apache Server","permalink":"/blog/cors-setup-apache/"},"nextItem":{"title":"Simple JWT Login in the News","permalink":"/blog/simple-jwt-login-wp-glob/"}},"content":":::warning Updated November 2026\\nThis SDK was built for Simple JWT Login 3.x. Its `refreshToken()` method still uses the 3.x refresh flow, so for plugin 4.x see [Refresh Token](/docs/refresh-token/).\\n:::\\n\\nThe JavaScript SDK for Simple JWT Login is out. Install it with npm:\\n\\n```bash\\nnpm install simple-jwt-login\\n```\\n\\nor with yarn:\\n\\n```bash\\nyarn add simple-jwt-login\\n```\\n\x3c!--truncate--\x3e\\n\\nThe source code is on GitHub: [https://github.com/simple-jwt-login/js-sdk](https://github.com/simple-jwt-login/js-sdk). Star the repository, read the code, open issues, or share it with others.\\n\\nWith a few lines of code, you can call any Simple JWT Login endpoint. This example registers a user:\\n\\n```js\\nimport { SimpleJwtLogin } from \\"simple-jwt-login\\";\\n\\nconst simpleJwtLogin = new SimpleJwtLogin(\\n  \\"https://your-domain.com\\",\\n  \\"/simple-jwt-login/v1\\",\\n  \\"AUTH_KEY\\"\\n);\\n\\n// The SDK passes the response to this callback instead of returning it.\\nsimpleJwtLogin.withCallback((response, status) => {\\n  console.log(status, response);\\n});\\n\\nsimpleJwtLogin.registerUser(\\n  {\\n    email: \\"me@mydomain.com\\",\\n    password: \\"my-secret-password\\",\\n    nickname: \\"coolnickname\\",\\n  },\\n  \\"MY_AUTH_KEY\\"\\n);\\n```\\n\\nThe SDK covers every endpoint:\\n- Autologin to WordPress\\n- Delete a user\\n- Register a user\\n- Reset a user\'s password\\n- Change a user\'s password\\n- Authenticate to WordPress\\n- Refresh a token\\n- Validate a token\\n- Revoke a token\\n\\nFor a step-by-step walkthrough, see [Using the JavaScript SDK in a React App](/blog/javascript-sdk-usage-react/)."},{"id":"/simple-jwt-login-wp-glob/","metadata":{"permalink":"/blog/simple-jwt-login-wp-glob/","editUrl":"https://github.com/simple-jwt-login/website/tree/main/blog/2022-08-23-wp-glob-article.md","source":"@site/blog/2022-08-23-wp-glob-article.md","title":"Simple JWT Login in the News","description":"WPGlob featured Simple JWT Login in its roundup of the best WordPress password management and authentication plugins.","date":"2022-08-23T00:00:00.000Z","tags":[{"inline":false,"label":"News","permalink":"/blog/tags/tags/news","description":"Plugin news"}],"readingTime":0.33,"hasTruncateMarker":true,"authors":[{"name":"Nicu Micle","title":"Creator of Simple JWT Login","url":"https://github.com/nicumicle","page":{"permalink":"/blog/authors/nicumicle"},"socials":{"x":"https://x.com/nicumicle","github":"https://github.com/nicumicle"},"imageURL":"https://github.com/nicumicle.png","key":"nicumicle"}],"frontMatter":{"title":"Simple JWT Login in the News","description":"WPGlob featured Simple JWT Login in its roundup of the best WordPress password management and authentication plugins.","keywords":["Simple JWT Login","WordPress plugin","press","password management"],"slug":"/simple-jwt-login-wp-glob/","hide_table_of_contents":false,"authors":"nicumicle","tags":["news"],"image":"/assets/images/social-card.png"},"unlisted":false,"prevItem":{"title":"JavaScript SDK Released","permalink":"/blog/simple-jwt-login-js-sdk-0.1.1/"},"nextItem":{"title":"MailPoet Add-on Released","permalink":"/blog/simple-jwt-login-mailpoet/"}},"content":"WPGlob featured Simple JWT Login in its article \\"Best List of Password Management Plugins for WordPress.\\"\\n\\n\x3c!-- truncate --\x3e\\nIt\'s great to be listed next to so many other useful plugins.\\n\\n[Read the article on WPGlob](https://wpglob.com/best-list-of-password-management-plugins-for-wordpress/).\\n\\nTo promote your own WordPress plugin, visit WPGlob\'s <a href=\\"https://wpglob.com/promote-wordpress-plugin/\\" rel=\\"external\\">Promote WordPress plugin</a> page."},{"id":"/simple-jwt-login-mailpoet/","metadata":{"permalink":"/blog/simple-jwt-login-mailpoet/","editUrl":"https://github.com/simple-jwt-login/website/tree/main/blog/2022-04-25-mailpoet-addon.md","source":"@site/blog/2022-04-25-mailpoet-addon.md","title":"MailPoet Add-on Released","description":"Simple JWT Login\'s MailPoet add-on lets you embed personalized, one-click magic-link logins directly inside MailPoet newsletter campaigns.","date":"2022-04-25T00:00:00.000Z","tags":[{"inline":false,"label":"News","permalink":"/blog/tags/tags/news","description":"Plugin news"},{"inline":false,"label":"Add-on","permalink":"/blog/tags/tags/add-on","description":"Plugin Addons"}],"readingTime":0.41,"hasTruncateMarker":true,"authors":[{"name":"Nicu Micle","title":"Creator of Simple JWT Login","url":"https://github.com/nicumicle","page":{"permalink":"/blog/authors/nicumicle"},"socials":{"x":"https://x.com/nicumicle","github":"https://github.com/nicumicle"},"imageURL":"https://github.com/nicumicle.png","key":"nicumicle"}],"frontMatter":{"title":"MailPoet Add-on Released","description":"Simple JWT Login\'s MailPoet add-on lets you embed personalized, one-click magic-link logins directly inside MailPoet newsletter campaigns.","keywords":["MailPoet","magic link login","WordPress plugin","autologin","JWT authentication"],"slug":"/simple-jwt-login-mailpoet/","hide_table_of_contents":false,"authors":"nicumicle","tags":["news","add-on"],"image":"/assets/images/social-card.png"},"unlisted":false,"prevItem":{"title":"Simple JWT Login in the News","permalink":"/blog/simple-jwt-login-wp-glob/"},"nextItem":{"title":"Welcome to the New Simple JWT Login Site","permalink":"/blog/simple-jwt-login-plus-docusaurus/"}},"content":"The first add-on for the Simple JWT Login plugin is out.\\n\\nThe MailPoet add-on adds autologin links to your newsletters.\\n\\n\x3c!--truncate--\x3e\\n\\n![Simple JWT Login MailPoet add-on banner](https://ps.w.org/simple-jwt-login-mailpoet/assets/banner-1544x500.png)\\n\\nSubscribers who click the link in a MailPoet newsletter are logged in to your WordPress site with a JWT, with no password needed.\\n\\nThe add-on provides shortcodes to use in your MailPoet templates.\\n\\n[Read the MailPoet add-on documentation](/docs/mailpoet)"},{"id":"simple-jwt-login-plus-docusaurus/","metadata":{"permalink":"/blog/simple-jwt-login-plus-docusaurus/","editUrl":"https://github.com/simple-jwt-login/website/tree/main/blog/2022-02-27-hello-docusaurus-v2.md","source":"@site/blog/2022-02-27-hello-docusaurus-v2.md","title":"Welcome to the New Simple JWT Login Site","description":"Simple JWT Login\'s documentation and blog have moved to a new Docusaurus-powered site, with better docs and a smoother experience for WordPress developers.","date":"2022-02-27T00:00:00.000Z","tags":[{"inline":false,"label":"News","permalink":"/blog/tags/tags/news","description":"Plugin news"}],"readingTime":0.91,"hasTruncateMarker":true,"authors":[{"name":"Nicu Micle","title":"Creator of Simple JWT Login","url":"https://github.com/nicumicle","page":{"permalink":"/blog/authors/nicumicle"},"socials":{"x":"https://x.com/nicumicle","github":"https://github.com/nicumicle"},"imageURL":"https://github.com/nicumicle.png","key":"nicumicle"}],"frontMatter":{"title":"Welcome to the New Simple JWT Login Site","description":"Simple JWT Login\'s documentation and blog have moved to a new Docusaurus-powered site, with better docs and a smoother experience for WordPress developers.","keywords":["Simple JWT Login","WordPress plugin","JWT authentication","Docusaurus","documentation"],"slug":"simple-jwt-login-plus-docusaurus/","hide_table_of_contents":false,"authors":"nicumicle","tags":["news"],"image":"/assets/images/social-card.png"},"unlisted":false,"prevItem":{"title":"MailPoet Add-on Released","permalink":"/blog/simple-jwt-login-mailpoet/"}},"content":":::info Update\\nThe site was redesigned again in 2026 - see [A Faster, Smarter New Website Design](/blog/new-website-design-2026/).\\n:::\\n\\nThe Simple JWT Login website now runs on [**Docusaurus 2**](https://docusaurus.io/).\\n\\nDocusaurus makes it simple to write the documentation and build the website in one place. It was quick to learn, and writing the site in React is fun.\\n\\n\x3c!--truncate--\x3e\\n\\n## Previous Website\\n\\nThe previous documentation used [docsify](https://docsify.js.org/), another good documentation generator, and the website itself was written in PHP.\\n\\nChanging or adding pages was hard, because every page needed code for routes and for loading content.\\n\\n## About the Blog\\n\\nWriting the documentation was a good moment to start a blog too. It covers real-world use cases of the plugin and announces new releases.\\n\\nTo learn about new features, or tips and tricks for building your site, follow this blog.\\n\\nThe documentation is also going to be public on GitHub, so anybody can suggest a fix or an improvement. It\'s written for you, so help from the community makes it easier for every new user to get started."}]}}')}}]);